traveling-salesman-problem.pseudocode:
def tour_length(tour, d):
    n = len(tour)
    return sum(d[tour[i]][tour[(i + 1) % n]]
               for i in range(n))

def two_opt(tour, d):
    best = tour_length(tour, d)
    improved = True
    while improved:  # 개선이 없을 때까지 반복
        improved = False
        for i in range(1, len(tour) - 1):
            for j in range(i + 1, len(tour)):
                # i..j 구간을 뒤집어 간선 두 개를 교체
                new = (tour[:i] + tour[i:j + 1][::-1]
                       + tour[j + 1:])
                length = tour_length(new, d)
                if length < best:
                    tour, best, improved = new, length, True
    return tour  # 지역 최적 (전역 최적은 보장 안 됨)

tree.pseudocode:
def preorder(n):  # 부모 먼저
    if n is None:
        return
    visit(n)
    for c in n.children:
        preorder(c)

def postorder(n):  # 자식 먼저
    if n is None:
        return
    for c in n.children:
        postorder(c)
    visit(n)

def level_order(root):  # 레벨 순(BFS)
    q = [root]
    while q:
        n = q.pop(0)
        visit(n)
        q.extend(n.children)

tree-of-thoughts.pseudocode:
def tot_bfs(problem, llm, steps, k, b):
    frontier = [[]]  # 각 상태 = 지금까지의 생각 목록
    for _ in range(steps):
        cands = []
        for state in frontier:
            # 상태마다 다음 생각 후보 k개 생성
            for t in llm.propose(problem, state, k):
                cands.append(state + [t])
        # LLM이 각 경로의 유망도를 스스로 평가
        cands.sort(key=lambda s: llm.evaluate(problem, s),
                   reverse=True)
        frontier = cands[:b]  # 상위 b개만 유지(빔)
    return frontier[0]

trie.pseudocode:
class TrieNode:
    def __init__(self):
        self.children = {}  # 문자 -> 자식 노드
        self.is_end = False

def insert(root, key):
    node = root
    for ch in key:
        if ch not in node.children:
            node.children[ch] = TrieNode()
        node = node.children[ch]
    node.is_end = True  # 키 종료 표시

def search(root, key, prefix=False):
    node = root
    for ch in key:  # O(키 길이), 원소 수와 무관
        if ch not in node.children:
            return False
        node = node.children[ch]
    return True if prefix else node.is_end

try-with-resources.pseudocode:
# try (r = open_resource()) { body(r) } 의 동작
r = open_resource()
primary = None
try:
    body(r)
except Exception as e:
    primary = e  # 주 예외 기록 후 전파
    raise
finally:
    if primary is None:
        r.close()  # 정상 경로: close 예외는 그대로 전파
    else:
        try:
            r.close()
        except Exception as e2:
            primary.add_suppressed(e2)  # 억제된 예외 보존
